gulp.task('images', function() {
   return gulp.src('images/**/*.+(jpg|jpeg|ico|png|gif|svg)')
    .pipe(imagemin()) // Optimize
    .pipe(rev())
    .pipe(gulp.dest('public/dist/images'))
    .pipe(rev.manifest())
    .pipe(gulp.dest('public/dist'));
